$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-private-filter-mouse.mjs'
try{[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log('{"error":"timeout"}');process.exit(0)},9000);
try{const t=(await(await fetch('http://127.0.0.1:17447/json/list')).json()).find(x=>x.id==='D229F01C94F7F6DF012309BB4CE211CD');const w=new WebSocket(t.webSocketDebuggerUrl);
await new Promise((ok,no)=>{w.addEventListener('open',ok,{once:true});w.addEventListener('error',no,{once:true})});
let i=1,resolveMap=new Map();w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(resolveMap.has(z.id)){resolveMap.get(z.id)(z);resolveMap.delete(z.id)}});
const send=(type)=>Promise.race([new Promise(ok=>{const id=i++;resolveMap.set(id,ok);w.send(JSON.stringify({id,method:'Input.dispatchMouseEvent',params:{type,x:159,y:756,button:'left',clickCount:1}}))}),new Promise(ok=>setTimeout(()=>ok({error:'timeout'}),1800))]);
const a=await send('mousePressed'),b=await send('mouseReleased');
console.log(JSON.stringify({pressed:!!a.result,released:!!b.result}));process.exit(0);
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,140)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item $tmp -Force -ErrorAction SilentlyContinue}
